import { normalizeSpeciesKey } from "@/lib/species/normalize";
import { SPECIES_ALIASES } from "@/constants";
import { candidateFormKeys } from "@/lib/species/candidateFormKeys";
import type { PokemonLanguage } from "./languages";

/**
 * One language's official game terms, generated by
 * scripts/generate-name-data.mjs into src/data/names/<language>.json. Every
 * table is keyed like the app's English data (see nameKey), so the app keeps
 * storing, exporting and calculating with English names and only translates
 * what it shows.
 */
export interface PokemonNames {
  species: Record<string, string>;
  moves: Record<string, string>;
  items: Record<string, string>;
  abilities: Record<string, string>;
  types: Record<string, string>;
  natures: Record<string, string>;
}

/** Translates the English names the app stores into the chosen language, falling back to the English name for anything untranslated. */
export interface PokemonText {
  language: PokemonLanguage;
  /** A Showdown species name ("Charizard-Mega-Y", "Raichu-Alola"). */
  species: (name: string) => string;
  /**
   * The form a species takes holding `item` — "Charizard" + "Charizardite Y"
   * is Mega Charizard Y. `englishName` is what English shows (the app's own
   * wording, e.g. Speed Tiers' "Mega Charizard Y").
   */
  speciesForm: (species: string, item: string | undefined, englishName: string) => string;
  move: (name: string) => string;
  item: (name: string) => string;
  ability: (name: string) => string;
  /** A type name ("Fire") — matched case-insensitively. */
  type: (name: string) => string;
  /** A nature name ("Adamant") — matched case-insensitively. */
  nature: (name: string) => string;
}

/** The lookup key for an English name — normalizeSpeciesKey, also folding the curly apostrophe some data uses ("Dragon’s Maw"). */
export function nameKey(name: string): string {
  return normalizeSpeciesKey(name.replace(/’/g, "'"));
}

function lookup(
  table: Record<string, string>,
  name: string,
  aliases?: Record<string, string>,
): string {
  if (!name) return name;
  const key = nameKey(name);
  return table[key] ?? (aliases?.[key] ? table[aliases[key]] : undefined) ?? name;
}

function identity(name: string): string {
  return name;
}

export const ENGLISH_POKEMON_TEXT: PokemonText = {
  language: "en",
  species: identity,
  speciesForm: (_species, _item, englishName) => englishName,
  move: identity,
  item: identity,
  ability: identity,
  type: identity,
  nature: identity,
};

export function createPokemonText(language: PokemonLanguage, names: PokemonNames): PokemonText {
  return {
    language,
    species: (name) => lookup(names.species, name, SPECIES_ALIASES),
    speciesForm: (species, item) => {
      for (const key of candidateFormKeys(species, item)) {
        const translated = names.species[key] ?? names.species[SPECIES_ALIASES[key]];
        if (translated) return translated;
      }
      return species;
    },
    move: (name) => lookup(names.moves, name),
    item: (name) => lookup(names.items, name),
    ability: (name) => lookup(names.abilities, name),
    type: (name) => lookup(names.types, name),
    nature: (name) => lookup(names.natures, name),
  };
}

/** Loads one language's names as its own chunk, so only the chosen language is downloaded. */
export async function loadPokemonNames(
  language: Exclude<PokemonLanguage, "en">,
): Promise<PokemonNames> {
  switch (language) {
    case "es":
      return (await import("@/data/names/es.json")).default;
    case "es-419":
      return (await import("@/data/names/es-419.json")).default;
  }
}
